/** Alt text for a manifest image in the given locale. */
export function localizeAlt(alt: string | undefined, locale: string | undefined): string {
  if (!alt) return "";
  if (!locale || locale === "en") return alt;
  const t = ALT[alt];
  if (!t) return "";
  return locale === "de" ? t.de : locale === "fr" ? t.fr : alt;
}
